# -*- coding: utf-8 -*-
exec(open('lib3.py',encoding='utf-8').read())
c='p4';B='PYTHON 2'
S=[]
S.append(TITLE('TIN HỌC · PYTHON 2','RẼ NHÁNH VÀ<br>VÒNG LẶP','if – elif – else, for với range, while, break, continue, vòng lặp lồng, kĩ thuật trace.',['if','for','while','break','trace']))
S.append(goals(c,B,['Viết cấu trúc <b>rẽ nhánh</b> if, if-else, if-elif-else.','Dùng <b>for … in range</b> và <b>while</b> đúng số lần lặp.','Dùng <b>break, continue</b>; viết <b>vòng lặp lồng</b>.','Thành thạo <b>kĩ thuật trace</b> (theo dõi bảng giá trị).','Giải các bài toán đếm, tổng, tìm max, kiểm tra tính chất.'],['Rẽ nhánh','Vòng lặp for và range','Vòng lặp while','break, continue, lồng nhau','Trace, bài toán mẫu, HSG']))
S.append(PYR(c,B+' · 1','Rẽ nhánh if – else','x = int(input())\nif x % 2 == 0:\n    print("chẵn")\nelse:\n    print("lẻ")',KEY('Sau <b>if điều_kiện:</b> và <b>else:</b> phải có <b>dấu hai chấm</b>; khối lệnh <b>thụt lề</b> đều nhau (thường 4 dấu cách).'),24,inp='7\n',lab='Kết quả (nhập 7)'))
S.append(PYR(c,B+' · 1','if – elif – else','d = float(input())\nif d >= 8:\n    print("Giỏi")\nelif d >= 6.5:\n    print("Khá")\nelif d >= 5:\n    print("Trung bình")\nelse:\n    print("Yếu")',KEY('Các nhánh được xét <b>từ trên xuống</b>; gặp nhánh đúng đầu tiên thì <b>bỏ qua</b> các nhánh còn lại.')+WARN('Thứ tự điều kiện rất quan trọng: đặt <code>d &gt;= 5</code> lên đầu thì mọi điểm từ 5 trở lên đều thành “Trung bình”.'),22,inp='7.2\n',lab='Kết quả (nhập 7.2)'))
S.append(S2(c,B+' · 1','Thụt lề quyết định khối lệnh',CODE('x = 5\nif x > 3:\n    print("A")\n    print("B")\nprint("C")',24),RES(OUT(RUN('x = 5\nif x > 3:\n    print("A")\n    print("B")\nprint("C")'),28),'Kết quả chạy')+WARN('<code>print("C")</code> <b>không thụt lề</b> nên nằm ngoài if và luôn được chạy. Thụt sai là lỗi <b>IndentationError</b> hoặc sai kết quả.')))
S.append(PYR(c,B+' · 1','Điều kiện ghép và lồng nhau','a, b, c = 3, 4, 5\nif a + b > c and b + c > a and a + c > b:\n    print("là 3 cạnh tam giác")\nx = 12\nif x > 0:\n    if x % 2 == 0:\n        print("dương chẵn")\n    else:\n        print("dương lẻ")',KEY('Dùng <b>and, or, not</b> để ghép điều kiện; if có thể <b>lồng</b> trong if.'),22))
S.append(PYR(c,B+' · 2','for với range(n)','for i in range(5):\n    print(i, end=" ")\nprint()\nfor i in range(3):\n    print("Tin học")',KEY('<code>range(n)</code> tạo dãy <b>0, 1, …, n-1</b> (n số, <b>không có n</b>); vòng lặp chạy <b>đúng n lần</b>.'),24))
S.append(TB(c,B+' · 2','Ba dạng của range',['Dạng','Dãy tạo ra','Ví dụ'],[['<code>range(n)</code>','0, 1, …, n-1','<code>range(4)</code> → 0 1 2 3'],['<code>range(a, b)</code>','a, a+1, …, <b>b-1</b>','<code>range(2, 6)</code> → 2 3 4 5'],['<code>range(a, b, k)</code>','a, a+k, … (<b>trước b</b>)','<code>range(1, 10, 3)</code> → 1 4 7'],['bước âm','giảm dần','<code>range(5, 0, -2)</code> → 5 3 1']],mono=1,note=KEY('Số lần lặp của <code>range(a, b)</code> là <b>b - a</b> (nếu b &gt; a). Giá trị <b>b không bao giờ được lấy</b>.')))
S.append(PYR(c,B+' · 2','Tổng và đếm bằng for','s = 0\nfor i in range(1, 101):\n    s += i\nprint(s)\n\nd = 0\nfor i in range(1, 101):\n    if i % 3 == 0:\n        d += 1\nprint(d)',KEY('Mẫu <b>cộng dồn</b>: khởi tạo <code>s = 0</code> trước vòng lặp, rồi <code>s += …</code>. Mẫu <b>đếm</b>: <code>d += 1</code> khi thoả điều kiện.'),22))
S.append(PYR(c,B+' · 2','Vòng for duyệt xâu và danh sách','for ch in "Tin":\n    print(ch)\nfor x in [4, 9, 2]:\n    print(x * 2, end=" ")\nprint()\nfor i, x in enumerate(["a", "b"]):\n    print(i, x)',KEY('<code>for … in</code> duyệt trực tiếp từng phần tử của xâu, danh sách. <b>enumerate</b> cho cả chỉ số và giá trị.'),22))
S.append(PYR(c,B+' · 3','Vòng lặp while','n = 1\nwhile n < 100:\n    n = n * 2\n    print(n, end=" ")\nprint()\nprint("n =", n)',KEY('<b>while điều_kiện:</b> lặp khi điều kiện còn <b>đúng</b>; dùng khi <b>chưa biết trước số lần lặp</b>.')+WARN('Phải có lệnh làm điều kiện <b>thay đổi</b> trong thân, nếu không sẽ lặp <b>vô hạn</b>.'),24))
S.append(PYR(c,B+' · 3','while: tách chữ số','n = 5729\ns = 0\nwhile n > 0:\n    s += n % 10\n    n //= 10\nprint(s)',KEY('Mẫu kinh điển: lấy <b>n % 10</b> rồi <b>n //= 10</b> cho đến khi n = 0. Ở đây tổng chữ số 5+7+2+9 = 23.'),24))
S.append(PYR(c,B+' · 3','while với điều kiện dừng nhập','tong = 0\nx = int(input())\nwhile x != 0:\n    tong += x\n    x = int(input())\nprint("Tổng:", tong)',KEY('Nhập dãy số kết thúc bằng <b>0</b>: đọc trước vòng lặp, đọc tiếp ở cuối thân (kĩ thuật <b>lính canh</b>).'),22,inp='5\n8\n-2\n0\n',lab='Kết quả (nhập 5, 8, -2, 0)'))
S.append(TB(c,B+' · 3','So sánh for và while',['','for','while'],[['Dùng khi','biết trước số lần lặp hoặc duyệt dãy','chưa biết số lần, lặp theo điều kiện'],['Biến đếm','tự cập nhật theo range','<b>tự viết</b> lệnh cập nhật'],['Nguy cơ','ít','<b>lặp vô hạn</b> nếu quên cập nhật'],['Ví dụ','tính tổng 1..n','tách chữ số, đọc đến khi gặp 0']],note=KEY('Mọi vòng for đều viết được bằng while; ngược lại không phải lúc nào cũng gọn bằng for.')))
S.append(PYR(c,B+' · 4','break: thoát vòng lặp','for i in range(2, 20):\n    if i * i > 50:\n        print("dừng ở", i)\n        break\nelse:\n    print("không dừng")',KEY('<b>break</b> thoát <b>ngay</b> khỏi vòng lặp <b>trong cùng</b> chứa nó. Khối <code>else</code> của vòng lặp chỉ chạy khi vòng lặp <b>kết thúc bình thường</b> (không break).'),22))
S.append(PYR(c,B+' · 4','continue: bỏ qua lượt này','for i in range(1, 11):\n    if i % 3 == 0:\n        continue\n    print(i, end=" ")\nprint()',KEY('<b>continue</b> bỏ phần còn lại của lượt lặp hiện tại và <b>sang lượt kế tiếp</b>, không thoát vòng lặp.'),24))
S.append(PYR(c,B+' · 4','Kiểm tra số nguyên tố','n = int(input())\nlaNT = n > 1\nfor i in range(2, int(n ** 0.5) + 1):\n    if n % i == 0:\n        laNT = False\n        break\nprint("nguyên tố" if laNT else "hợp số")',KEY('Chỉ cần thử ước <b>đến √n</b>; gặp ước thì <b>break</b>. Biến <b>cờ</b> <code>laNT</code> ghi lại kết quả.'),21,inp='29\n',lab='Kết quả (nhập 29)'))
S.append(PYR(c,B+' · 4','Vòng lặp lồng nhau: hình sao','for i in range(1, 5):\n    for j in range(i):\n        print("*", end="")\n    print()',KEY('Vòng <b>ngoài</b> chạy i = 1..4 (số dòng); với mỗi i vòng <b>trong</b> chạy i lần. Tổng số lần in = 1+2+3+4 = <b>10</b>.'),24))
S.append(PYR(c,B+' · 4','Lồng nhau: bảng cửu chương','for i in range(2, 5):\n    for j in range(1, 4):\n        print(f"{i}x{j}={i*j}", end="  ")\n    print()',KEY('Số lần chạy thân vòng trong = (số lần vòng ngoài) × (số lần vòng trong) = 3 × 3 = <b>9</b>.'),22))
S.append(S2(c,B+' · 5','Kĩ thuật trace: bảng theo dõi',CODE('s = 0\nfor i in range(1, 5):\n    if i % 2 == 1:\n        s += i\n    else:\n        s -= i\nprint(s)',24),T(tr('i','i%2','s sau lượt',h=True)+tr('1','1','0+1 = 1')+tr('2','0','1−2 = −1')+tr('3','1','−1+3 = 2')+tr('4','0','2−4 = −2'))+KEY('Kết quả in ra: <b>-2</b>. Mỗi lượt ghi lại <b>giá trị biến</b>; đây là cách kiểm tra bài “đoán kết quả”.')))
S.append(S2(c,B+' · 5','Trace vòng while có chia dư',CODE('a, b = 48, 18\nwhile b != 0:\n    a, b = b, a % b\nprint(a)',24),T(tr('Lượt','a','b',h=True)+tr('đầu','48','18')+tr('1','18','48%18 = 12')+tr('2','12','18%12 = 6')+tr('3','6','12%6 = 0'))+KEY('Dừng khi b = 0, in <b>a = 6</b>: đây là thuật toán <b>Euclid</b> tìm ƯCLN(48, 18).')))
S.append(PYR(c,B+' · 5','Bài toán mẫu: tìm max và vị trí','a = [4, 9, 2, 9, 7]\nm = a[0]\nvt = 0\nfor i in range(1, len(a)):\n    if a[i] > m:\n        m = a[i]\n        vt = i\nprint(m, vt)',KEY('Mẫu <b>tìm lớn nhất</b>: khởi tạo bằng phần tử đầu, so sánh <b>&gt;</b> thì cập nhật. Vì dùng <b>&gt;</b> (không phải &gt;=) nên giữ vị trí <b>đầu tiên</b> của 9 (vt = 1).'),22))
S+=END(c,B,['<b>if / elif / else</b>: thụt lề và dấu <b>:</b>; xét nhánh từ trên xuống.','<code>range(a, b, k)</code>: <b>không lấy b</b>; số lần = (b-a)/k làm tròn lên.','<b>for</b> biết số lần; <b>while</b> theo điều kiện, nhớ cập nhật biến.','<b>break</b> thoát vòng trong cùng; <b>continue</b> sang lượt kế tiếp.','Vòng lồng: số lần = tích; <b>trace</b> bằng bảng giá trị.'],[('Cộng dồn','s = 0; s += x'),('Đếm','d = 0; d += 1'),('Tìm max','m = a[0]'),('Thoát sớm','break')],'Vòng lặp vô hạn khi quên cập nhật biến trong while; thụt lề sai.',['<code>range(5)</code> có 5 số nhưng <b>không có 5</b>.','<code>for … else</code>: else chạy khi <b>không</b> break.','<code>break</code> chỉ thoát vòng <b>trong cùng</b>, không thoát cả hai vòng lồng.','Đếm số lần lặp của vòng <code>for i in range(1, n): for j in range(i, n)</code> cần tính tổng.'],['<b>Biến cờ</b> (flag) ghi nhớ sự kiện trong vòng lặp.','<b>Lính canh</b> (sentinel): giá trị đặc biệt kết thúc nhập.','<b>Độ phức tạp</b>: vòng lồng hai lớp ~ n² phép (học ở Python 5).'],
 [('<code>for i in range(2, 10, 3)</code> in ra những số nào?',),('Có bao nhiêu lần chạy thân vòng lặp: <code>for i in range(3): for j in range(4): pass</code>?',),('Viết chương trình nhập n, in tổng các số chẵn từ 1 đến n.',),('Viết chương trình đếm số chữ số của n bằng while.',),('Khác nhau giữa break và continue?',)],
 [(RUN('print(*range(2, 10, 3))')+' (2, 5, 8)',),('3 × 4 = <b>12</b> lần.',),('<code>n=int(input()); s=0\\nfor i in range(2, n+1, 2): s += i\\nprint(s)</code>',),('<code>n=abs(int(input())); d=0\\nwhile n&gt;0: d+=1; n//=10</code> (cần xử lí riêng n = 0).',),('<b>break</b> thoát hẳn vòng lặp; <b>continue</b> bỏ lượt hiện tại rồi tiếp tục lượt sau.',)],
 [('Trace, cho biết kết quả in ra:',"s = 0\nfor i in range(1, 6):\n    if i % 2 == 0:\n        continue\n    s += i * i\nprint(s)"),
  ('Trace:',"a, b = 0, 1\nfor _ in range(6):\n    a, b = b, a + b\nprint(a)"),
  ('Trace:',"n, d = 36, 0\nwhile n % 2 == 0:\n    n //= 2\n    d += 1\nprint(n, d)"),
  ('Có bao nhiêu dấu * được in?',"for i in range(1, 6):\n    for j in range(i, 6):\n        print('*', end='')\n    print()"),
  ('Viết chương trình in tất cả số có 3 chữ số mà tổng lập phương các chữ số bằng chính nó (Armstrong).',),
  ('Đoạn sau in ra gì và vì sao?',"for i in range(3):\n    print(i)\nelse:\n    print('xong')")],
 [(RUN("s = 0\nfor i in range(1, 6):\n    if i % 2 == 0:\n        continue\n    s += i * i\nprint(s)")+' (1+9+25)',),
  (RUN("a, b = 0, 1\nfor _ in range(6):\n    a, b = b, a + b\nprint(a)")+' (dãy Fibonacci: 0,1,1,2,3,5,8)',),
  (RUN("n, d = 36, 0\nwhile n % 2 == 0:\n    n //= 2\n    d += 1\nprint(n, d)")+' (36→18→9)',),
  (RUN("for i in range(1, 6):\n    for j in range(i, 6):\n        print('*', end='')\n    print()").replace('\n','/')+' → 5+4+3+2+1 = <b>15</b>',),
  ('<code>for n in range(100, 1000): a,b,c=n//100,n//10%10,n%10\\n if a**3+b**3+c**3==n: print(n)</code> → '+RUN('print(*[n for n in range(100,1000) if sum(int(x)**3 for x in str(n))==n])'),),
  (RUN("for i in range(3):\n    print(i)\nelse:\n    print('xong')").replace('\n',', ')+': vòng for kết thúc bình thường (không break) nên else chạy.',)],hper=2)
mkdeck('p2.html','Python 2 · Rẽ nhánh và vòng lặp',S)
